#!/usr/bin/env python3
import sys, os, re, json, gzip, codecs, csv, io, datetime
import xml.etree.ElementTree as ET
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP

KG = {'kg': Fraction(1), 'g': Fraction(1, 1000),
      'lb': Fraction('0.45359237'), 'oz': Fraction('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
UNITS = set(KG)
HEADER_NAMES = {'id', 'ref', 'type', 'typ', 'kind', 't', 'rec', 'shipped', 'date', 'booked',
                'gross', 'net', 'gross_kg', 'net_kg', 'weight', 'status', 'state', 'note'}
TYPE_COLS = ('type', 'typ', 'kind', 't', 'rec')
ID_COLS = ('id', 'ref')
DATE_COLS = ('shipped', 'date')
WEIGHT_COLS = ('gross', 'gross_kg', 'weight')
STATUS_COLS = ('status', 'state')
CODES = {'dlv': 'delivered', 'dll': 'delivered_late'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'harbor': 'iso',
             'west': 'DD.MM.YYYY'}
DELIMS = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    enc = 'utf-8'
    m = re.search(rb'(?im)^#[ \t]*charset[ \t]*:[ \t]*([A-Za-z0-9_.:-]+)', b[:4096])
    if m:
        try:
            enc = codecs.lookup(m.group(1).decode('ascii')).name
        except LookupError:
            pass
    return b.decode(enc, errors='replace')


def id_num(s):
    m = re.search(r'\d+', s or '')
    return int(m.group()) if m else None


def norm_status(s):
    s = (s or '').strip().lower().replace(' ', '_').replace('-', '_')
    return CODES.get(s, s)


def norm_type(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'correction'
    return 'new'


def parse_weight(s, decimal_comma, default_unit):
    """returns Fraction kg"""
    s = (s or '').strip()
    m = re.match(r'^([-+]?[\d.,\s]*\d|[-+]?[.,]\d+)\s*([A-Za-z]*)$', s)
    if not m:
        raise ValueError('bad weight %r' % s)
    num, unit = m.group(1), m.group(2).lower()
    num = num.replace(' ', '')
    if decimal_comma:
        num = num.replace('.', '').replace(',', '.')
    else:
        num = num.replace(',', '')
    unit = unit or default_unit
    return Fraction(Decimal(num)) * KG[unit]


def date_to_month(s, form):
    s = (s or '').strip()
    f = (form or 'iso').strip()
    fl = f.lower()
    if fl == 'serial':
        d = datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(s)))
        if int(float(s)) >= 60:
            d = d - datetime.timedelta(days=1)
        # day 1 = 1899-12-31 as documented (no 1900 leap bug)
        d = datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(s)) - 1)
        return '%04d-%02d' % (d.year, d.month)
    nums = re.findall(r'\d+', s)
    if fl in ('iso', 'ymd', 'yyyy-mm-dd', 'yyyymmdd'):
        if len(nums) == 1 and len(nums[0]) == 8:
            y, m = nums[0][:4], nums[0][4:6]
        else:
            y, m = nums[0], nums[1]
    elif fl in ('dmy', 'dd-mm-yyyy', 'dd.mm.yyyy', 'dd/mm/yyyy'):
        m, y = nums[1], nums[2]
    elif fl in ('mm/dd/yyyy', 'mdy'):
        m, y = nums[0], nums[2]
    elif fl == 'yyyyddd':
        d = datetime.date(int(nums[0][:4]), 1, 1) + datetime.timedelta(days=int(nums[0][4:]) - 1)
        return '%04d-%02d' % (d.year, d.month)
    else:
        raise ValueError('unknown date form %r' % f)
    return '%04d-%02d' % (int(y), int(m))


def time_to_month(s):
    s = (s or '').strip()
    m = re.match(r'^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$', s)
    if m:
        return '%04d-%02d' % (int(m.group(3)), MONTHS[m.group(2).lower()])
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        return s[:7]
    t = s.replace('Z', '+00:00').replace('z', '+00:00')
    dt = datetime.datetime.fromisoformat(t)
    if dt.tzinfo is not None:
        dt = dt.astimezone(datetime.timezone.utc)
    return '%04d-%02d' % (dt.year, dt.month)


def rec(num, typ, month, kg, status):
    return {'num': num, 'type': typ, 'month': month, 'kg': kg, 'status': status}


# ---------------- delimited ----------------
def logical_lines(text):
    """yield ('comment', line) or ('row', chunk) respecting quotes"""
    buf = None
    for line in text.split('\n'):
        line = line.rstrip('\r') if buf is None else line
        if buf is None:
            if line.strip() == '':
                continue
            if line.startswith('#'):
                yield 'comment', line
                continue
            if line.count('"') % 2 == 0:
                yield 'row', line
            else:
                buf = line
        else:
            buf += '\n' + line.rstrip('\r')
            if buf.count('"') % 2 == 0:
                yield 'row', buf
                buf = None
    if buf is not None:
        yield 'row', buf


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    seq = None
    dirs = {}
    header = None
    out = []
    for kind, chunk in logical_lines(text):
        if kind == 'comment':
            m = re.match(r'^#\s*([A-Za-z][A-Za-z _-]*?)\s*:\s*(.*?)\s*$', chunk)
            if m:
                name = re.sub(r'[\s_-]+', ' ', m.group(1).lower())
                dirs[name] = m.group(2)
                if name == 'seq' and seq is None:
                    mm = re.search(r'\d+', m.group(2))
                    seq = int(mm.group()) if mm else None
            else:
                m = re.search(r'seq\s*=\s*(\d+)', chunk)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if delim == ',':
            row = next(csv.reader([chunk], delimiter=',', quotechar='"'))
        else:
            row = chunk.split(delim)
        cells = [c.strip().lower() for c in row]
        if cells and all(c in HEADER_NAMES for c in cells):
            header = cells
            continue
        if header is None:
            continue
        wcol = next((c for c in WEIGHT_COLS if c in header), None)
        row_unit = None
        if len(row) == len(header) + 1 and wcol:
            wi = header.index(wcol)
            if row[wi + 1].strip().lower() in UNITS:
                row_unit = row[wi + 1].strip().lower()
                row = row[:wi + 1] + row[wi + 2:]
        d = dict(zip(header, row))
        idc = next((c for c in ID_COLS if c in d), None)
        if idc is None or not re.match(r'^\s*SH\W*\d', d[idc], re.I):
            continue
        num = id_num(d[idc])
        tcol = next((c for c in TYPE_COLS if c in d), None)
        typ = norm_type(d[tcol]) if tcol else 'new'
        if typ == 'void':
            out.append(rec(num, 'void', None, None, None))
            continue
        # unit
        dunit = 'kg'
        for k in ('weight unit', 'unit'):
            if k in dirs:
                dunit = re.match(r'\s*(\w+)', dirs[k]).group(1).lower()
                break
        if row_unit:
            dunit = row_unit
        if wcol == 'gross_kg':
            dunit = 'kg'
        kg = parse_weight(d[wcol], depot == 'west', dunit)
        form = BASE_DATE[depot]
        if depot != 'west':
            for k in ('dates', 'date format', 'date'):
                if k in dirs:
                    form = dirs[k]
                    break
        dcol = next(c for c in DATE_COLS if c in d)
        month = date_to_month(d[dcol], form)
        scol = next(c for c in STATUS_COLS if c in d)
        out.append(rec(num, typ, month, kg, norm_status(d[scol])))
    return seq, out


# ---------------- fixed width ----------------
LAYOUTS = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26),
                dfmt='yyyyddd', wunit=Fraction(1, 1000)),
    'FW2': dict(len=43, id=(1, 10), type=(0, 1), shipped=(10, 18), weight=(18, 26), status=(26, 27),
                dfmt='yyyymmdd', wunit=Fraction(1, 100)),
    'FW3': dict(len=41, id=(0, 9), type=(16, 17), shipped=(9, 16), weight=(17, 24), status=(24, 25),
                dfmt='yyyyddd', wunit=KG['lb'] / 10),
}
BYLEN = {v['len']: k for k, v in LAYOUTS.items()}


def parse_fixed(text):
    seq = None
    cur = None
    out = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.strip() == '':
            continue
        if '\f' in line or 'SHIPMENT LISTING' in line.upper():
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                cur = m.group(1).upper()
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        name = BYLEN.get(len(line))
        if name is None:
            if cur is None:
                continue
            name = cur
            line = line.ljust(LAYOUTS[name]['len'])[:LAYOUTS[name]['len']]
        L = LAYOUTS[name]
        f = lambda k: line[L[k][0]:L[k][1]]
        num = id_num(f('id'))
        if num is None:
            continue
        typ = norm_type(f('type'))
        if typ == 'void':
            out.append(rec(num, 'void', None, None, None))
            continue
        ship = f('shipped').strip()
        month = date_to_month(ship, L['dfmt'])
        kg = Fraction(int(f('weight'))) * L['wunit']
        st = {'D': 'delivered', 'L': 'delivered_late'}.get(f('status').strip().upper(), 'other')
        out.append(rec(num, typ, month, kg, st))
    return seq, out


# ---------------- XML ----------------
def parse_xml(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    out = []
    for sh in root.iter('shipment'):
        num = id_num(sh.get('id'))
        typ = norm_type(sh.get('type'))
        if typ == 'void':
            out.append(rec(num, 'void', None, None, None))
            continue
        def val(name):
            if sh.get(name) is not None:
                return sh.get(name)
            e = sh.find(name)
            return e.text if e is not None and e.text else None
        w = sh.find('weight')
        unit = (w.get('unit') or sh.get('weight-unit') or runit).lower()
        kg = parse_weight(w.text, False, unit)
        month = time_to_month(val('shipped'))
        out.append(rec(num, typ, month, kg, norm_status(val('status'))))
    return seq, out


# ---------------- JSON lines ----------------
def parse_jsonl(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                if seq is None and o['meta'].get('seq') is not None:
                    seq = int(o['meta']['seq'])
                continue
            num = id_num(str(o.get('id')))
            typ = norm_type(o.get('kind'))
            if typ == 'void':
                out.append(rec(num, 'void', None, None, None))
                continue
            kg = None
            for k, x in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', k.lower())
                if m:
                    kg = parse_weight(str(x), False, m.group(1))
            if kg is None and 'weight' in o:
                kg = parse_weight(str(o['weight']), False, str(o.get('unit', 'kg')).lower())
            out.append(rec(num, typ, time_to_month(o['shipped_at']), kg, norm_status(o.get('status'))))
    return seq, out


def parse_file(depot, path):
    if depot == 'central':
        return parse_xml(path)
    text = read_text(path)
    if depot == 'north':
        return parse_jsonl(text)
    if depot == 'south':
        return parse_fixed(text)
    if depot in DELIMS:
        return parse_delimited(depot, text)
    stripped = text.lstrip()
    if stripped.startswith('<'):
        return parse_xml(path)
    raise ValueError('unknown depot ' + depot)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-', 1)[0]
        exports.setdefault(depot, [])
        try:
            seq, recs = parse_file(depot, p)
        except ValueError as e:
            if 'unknown depot' in str(e):
                continue
            raise
        exports[depot].append((seq if seq is not None else 0, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r['num']
                if r['type'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for n in current[depot]:
            owners.setdefault(n, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    dep = {d: [0, Fraction(0)] for d in exports}
    mon = {}
    for n, ds in owners.items():
        d = ds[0]
        r = current[d][n]
        if r['status'] in ('delivered', 'delivered_late'):
            dep[d][0] += 1
            dep[d][1] += r['kg']
            m = mon.setdefault(r['month'], [0, Fraction(0)])
            m[0] += 1
            m[1] += r['kg']

    def rnd(fr):
        d = Decimal(fr.numerator) / Decimal(fr.denominator) if False else None
        q = (fr * 100)
        i = (q.numerator * 2 + q.denominator) // (2 * q.denominator)
        return float(Decimal(i) / 100)
    result = {
        'depots': {d: {'shipments': v[0], 'total_kg': rnd(v[1])} for d, v in sorted(dep.items())},
        'months': {m: {'shipments': v[0], 'total_kg': rnd(v[1])} for m, v in sorted(mon.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main()
